-- QBR testopstelling — schema + synthetische testdata (Supabase / Postgres)
-- Draai dit in Supabase: SQL Editor -> New query -> plakken -> Run.

create table if not exists clients (
  id text primary key,
  name text not null,
  slug text,
  tenant_id text,
  datto_site text,
  datto_saas text,
  rocketcyber_customer text,
  itglue_org text,
  freshdesk_company text,
  bullphish_org text,
  grc_client text
);

create table if not exists qbr_snapshots (
  id bigint generated always as identity primary key,
  client text references clients(id),
  quarter text,
  generated_at timestamptz default now(),
  status text default 'published',
  data jsonb not null
);
create index if not exists qbr_snapshots_client_idx on qbr_snapshots (client, generated_at desc);

alter table clients enable row level security;
alter table qbr_snapshots enable row level security;
drop policy if exists "read clients" on clients;
drop policy if exists "read snapshots" on qbr_snapshots;
create policy "read clients" on clients for select to anon using (true);
create policy "read snapshots" on qbr_snapshots for select to anon using (status = 'published');

-- ---- Testdata ----
insert into clients (id, name) values
  ('demo1','De Jong Logistics B.V.'),
  ('demo2','Van Dijk Retail B.V.')
on conflict (id) do nothing;

